from docich.hanjuku_speedrun import hanjuku_policy as policy
from docich.hanjuku_speedrun.hanjuku_font import TextLine
from docich.hanjuku_speedrun.hanjuku_screen import Screen
from docich.hanjuku_speedrun.hanjuku.os_layer import roster
from docich.hanjuku_speedrun.hanjuku.state.regions import world as _world
from .test_hanjuku_multi_chikujou import castles, memory, open_build, quote, result


def chapter9_memory():
    mem = memory()
    mem['chapter'] = 9
    mem['month'] = '1-7'
    names = [name for name in policy.chart.CASTLE_NAMES[9] if name != 'ボス']
    home = policy.chart.home_castle(9)
    mem['captured'] = [name for name in names if name != home]
    _world(mem)['garrison'] = {
        name: ['どうし' if name == home else 'ゼウス'] for name in names
    }
    candidates = policy._chikujou_candidates(mem)
    mem['shop']['chikujou_tried'] = [name for name in candidates if name != 'イデ！']
    return mem


def native_list(names, selected, gold=None):
    lines = [TextLine(39 + i * 16, ((168, name),)) for i, name in enumerate(names)]
    index = names.index(selected)
    header = {'year': 1, 'month': 7, 'gold': gold} if gold is not None else None
    return Screen(lines, (144, 33 + index * 16, 164, 45 + index * 16),
                  ''.join(names) + 'どのしろをぞうちくなさいますか?',
                  header=header, kind='text')


def test_scroll_recognizes_half_width_exclamation_as_known_castle():
    mem = chapter9_memory()
    sub = {'kind': 'chikujou', 'build_wait': 0}
    screen = castles(on='イデ!', names=('イソ', 'オオキク', 'カラ', 'イデ!'))

    assert policy._chikujou_scroll(screen, mem, sub) == [policy.pad('down')]
    assert mem['_records'][-1]['decision'] == 'chikujou_scroll'
    assert mem['_records'][-1]['observed_metric']['visible'][-1] == 'イデ!'


def test_visible_maxed_level_returns_catalog_spelling():
    names = ('イソ', 'オオキク', 'カラ', 'イデ!')
    lines = [TextLine(39 + i * 16, ((168, name), (232, '5' if i == 3 else '1')))
             for i, name in enumerate(names)]
    screen = Screen(lines, (144, 33, 164, 45), ''.join(names), kind='text')

    assert policy._chikujou_visible_maxed(screen, {'chapter': 9}) == ['イデ！']


def test_selection_quote_and_result_keep_canonical_catalog_name():
    mem = chapter9_memory()
    sub = open_build(mem)
    screen = castles(on='イデ!', names=('イソ', 'オオキク', 'カラ', 'イデ!'))

    assert policy.month_sub_step(screen, mem) == [policy.pad('a')]
    assert sub['chosen'] == 'イデ！'
    assert policy.month_sub_step(quote('イデ!', gold=150, cost=5), mem) == [policy.pad('a')]
    assert sub['confirm_sent'] is True
    assert policy.month_sub_step(result('イデ!'), mem) == [policy.pad('a')]
    assert sub['upgraded'] is True
    assert sub['chosen'] == 'イデ！'


def test_continue_list_recognizes_folded_row_and_selects_canonical_name(monkeypatch):
    mem = chapter9_memory()
    candidates = policy._chikujou_candidates(mem)
    mem['shop']['chikujou_tried'] = [name for name in candidates if name != 'イデ！']
    mem['_run_identity'] = 'run-1'
    sub = {
        'kind': 'chikujou', 'key': '1-7', 'chikujou_version': 2,
        'chikujou_identity': 'run-1', 'chikujou_chapter': 9,
        'confirm_sent': True, 'upgraded': True, 'chosen': 'ハヤク',
        'quoted_cost': 5, 'confirm_gold': 150, 'rows_tried': [],
        'presses': 0,
    }
    mem['month_sub'] = sub
    mem['shop']['chikujou'] = 'check'
    monkeypatch.setattr(roster, 'run_identity', lambda value: value)
    monkeypatch.setattr(policy, '_finish_month_sub', lambda screen, mem, shop: True)
    screen = native_list(('イソ', 'オオキク', 'カラ', 'イデ!'), 'イデ!', gold=145)

    assert policy._chikujou_continue_list(screen, mem, sub) == [policy.pad('a')]
    assert mem['month_sub']['chosen'] == 'イデ！'


def test_refusal_updates_canonical_garrison_for_half_width_screen_name():
    mem = chapter9_memory()
    sub = open_build(mem)
    sub['chosen'] = 'イデ！'
    screen = Screen([], None, 'イデ!じょうはしょうぐんがおりませなんだ', kind='text')

